using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. Strongly-typed retrieval: JsonTypeInfo<T> --------------------------
// Wire up a default resolver so the options know about common types.
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// Generic overload returns JsonTypeInfo<T> directly – no cast needed.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata  : {personInfo.Type.Name}  (JsonTypeInfo<{personInfo.Type.Name}>)");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized with it  : {json}");

// --- 2. Probe without throwing: TryGetTypeInfo ----------------------------
// The DefaultJsonTypeInfoResolver can build metadata for any serialisable
// type, so we also show a resolver that only knows about one type to
// demonstrate a genuine "not found" result.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new LimitedResolver()
};

if (limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
    Console.WriteLine($"\nPerson   -> found   : {found.Type.Name}");
else
    Console.WriteLine("\nPerson   -> NOT found");

if (limited.TryGetTypeInfo(typeof(Order), out JsonTypeInfo? found2))
    Console.WriteLine($"Order    -> found   : {found2.Type.Name}");
else
    Console.WriteLine("Order    -> NOT found  (no exception thrown!)");

// --- types ----------------------------------------------------------------
record Person(string Name, int Age);
record Order(int Id, decimal Total);

// A resolver that only knows about Person.
sealed class LimitedResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
        => type == typeof(Person) ? _inner.GetTypeInfo(type, options) : null;
}

